#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head;  /* write position (next byte to write) */
    size_t tail;  /* read position (oldest byte) */
    size_t sz;    /* current number of filled slots */
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb;

    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = malloc(capacity);
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    rb->sz = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    size_t to_write;

    if (!rb || !data || len == 0)
        return 0;

    /* Free space = capacity - sz */
    to_write = len;
    if (to_write > rb->capacity - rb->sz)
        to_write = rb->capacity - rb->sz;

    for (size_t i = 0; i < to_write; ++i) {
        rb->buf[(rb->head + i) % rb->capacity] = data[i];
    }
    rb->head = (rb->head + to_write) % rb->capacity;
    rb->sz += to_write;

    return to_write;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t to_read;

    if (!rb || !out || len == 0)
        return 0;

    to_read = len;
    if (to_read > rb->sz)
        to_read = rb->sz;

    for (size_t i = 0; i < to_read; ++i) {
        out[i] = rb->buf[(rb->tail + i) % rb->capacity];
    }
    rb->tail = (rb->tail + to_read) % rb->capacity;
    rb->sz -= to_read;

    return to_read;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t to_copy;

    if (!rb || !out || len == 0)
        return 0;

    to_copy = len;
    if (to_copy > rb->sz)
        to_copy = rb->sz;

    for (size_t i = 0; i < to_copy; ++i) {
        out[i] = rb->buf[(rb->tail + i) % rb->capacity];
    }

    return to_copy;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->sz;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->sz = 0;
}

#include <stdio.h>
#include <string.h>
#include <assert.h>
#include "ringbuf.h"

#define EXPECT(cond, msg) do { \
    if (!(cond)) { printf("FAIL: %s\n", msg); return 1; } \
} while(0)

int main(void)
{
    /* rb_create / rb_capacity / rb_size */
    ringbuf_t *rb = rb_create(8);
    EXPECT(rb != NULL, "create");
    EXPECT(rb_capacity(rb) == 8, "capacity");
    EXPECT(rb_size(rb) == 0, "empty size");

    /* basic write + read */
    const char txt[] = "Hello";
    size_t n = rb_write(rb, (const uint8_t *)txt, strlen(txt));
    EXPECT(n == 5, "write count");
    EXPECT(rb_size(rb) == 5, "size after write");

    uint8_t buf[256];
    n = rb_read(rb, buf, sizeof(buf));
    EXPECT(n == 5, "read count");
    EXPECT(memcmp(buf, "Hello", 5) == 0, "data match");
    EXPECT(rb_size(rb) == 0, "size after read");

    /* wrap-around: fill partially, write more until it wraps */
    n = rb_write(rb, (const uint8_t *)"12345678", 8);
    EXPECT(n == 8, "fill 8");
    n = rb_read(rb, buf, 5);
    EXPECT(n == 5, "read 5");
    /* remaining in buffer: '678', then write at head */
    n = rb_write(rb, (const uint8_t *)"ABCD", 4);
    EXPECT(n == 3, "wrap-around write fits only 3");
    EXPECT(rb_size(rb) == 6, "size after partial write");

    /* peek */
    n = rb_peek(rb, buf, 256);
    EXPECT(n == 6, "peek count");
    EXPECT(memcmp(buf, "678AB", 5) == 0, "peek data");

    /* clear */
    rb_clear(rb);
    EXPECT(rb_size(rb) == 0, "size after clear");
    EXPECT(rb_capacity(rb) == 8, "capacity after clear");

    /* NULL safety */
    EXPECT(rb_write(NULL, (uint8_t *)"x", 1) == 0, "NULL write");
    EXPECT(rb_read(NULL, buf, 1) == 0, "NULL read");
    EXPECT(rb_peek(NULL, buf, 1) == 0, "NULL peek");
    EXPECT(rb_size(NULL) == 0, "NULL size");
    EXPECT(rb_capacity(NULL) == 0, "NULL capacity");
    rb_destroy(NULL); /* should not crash */

    /* create(0) invalid */
    EXPECT(rb_create(0) == NULL, "create zero cap");

    /* exact fit + wrap-around full cycle */
    ringbuf_t *rb2 = rb_create(4);
    rb_write(rb2, (uint8_t *)"ABCDEFGH", 8); /* should write 4 */
    uint8_t b2[256];
    size_t m = rb_read(rb2, b2, 8);
    EXPECT(m == 4, "wrapped read");
    EXPECT(memcmp(b2, "ABCD", 4) == 0, "wrapped data");
    rb_destroy(rb2);

    printf("ALL TESTS PASSED\n");
    return 0;
}

